using System;using System.Linq;using UnityEngine;using UnityEditor;using UnityEditor.IMGUI.Controls;
public sealed class TrainingSpatialAuthoring:MonoBehaviour {
 public enum ActionKind { Ground, Air, ThrowAttempt } public ActionKind action; public enum EditTarget { All, Sprite, Body, HitBox, HurtBox } public EditTarget editTarget;public int hurtIndex;
 public TrainingMoveSet moves;public TrainingApprovedCharacter character;public TrainingHurtboxProfile hurtboxes;public TrainingCommand command=TrainingCommand.Light;public float frame;public int facing=1;
 [NonSerialized]public TrainingMoveSpatialProfile draft;[NonSerialized]public SpriteRenderer preview;
 public TrainingAirAttackCandidate Candidate=>moves==null?null:command==TrainingCommand.Slash?moves.flyingKick:command==TrainingCommand.HeavySlash?moves.dropKick:command==TrainingCommand.AirStrongPunch?moves.airStrongPunch:command==TrainingCommand.AirStrongKick?moves.airStrongKick:command==TrainingCommand.AirDownStrongKick?moves.airDownStrongKick:command==TrainingCommand.AirSpecial2?moves.airSpecial2:null;
 public TrainingCommand[] Choices=>System.Enum.GetValues(typeof(TrainingCommand)).Cast<TrainingCommand>().Where(c=>action==ActionKind.ThrowAttempt?c==TrainingCommand.Throw:action==ActionKind.Ground?moves!=null&&moves.Find(c)!=null:AirCandidate(c)!=null).ToArray();
 TrainingAirAttackCandidate AirCandidate(TrainingCommand c){var saved=command;command=c;var value=Candidate;command=saved;return value;}
 TrainingMove AirMove=>moves==null?null:command==TrainingCommand.AirStrongPunch?moves.airStrongPunchMove:command==TrainingCommand.AirStrongKick?moves.airStrongKickMove:command==TrainingCommand.AirDownStrongKick?moves.airDownStrongKickMove:command==TrainingCommand.AirSpecial2?moves.airSpecial2Move:null;
 public TrainingMove Move {get{if(moves==null)return null;if(action==ActionKind.Ground)return moves.Find(command);if(action==ActionKind.ThrowAttempt){var t=moves.throwSettings;return t==null?null:new TrainingMove{command=TrainingCommand.Throw,startupFrames=t.startupFrames,activeFrames=t.activeFrames,recoveryFrames=t.recoveryFrames,center=t.boxCenter,halfSize=t.boxSize*.5f,spatialProfile=t.spatialProfile};}var c=Candidate;if(c==null)return null;return AirMove??new TrainingMove{command=command,startupFrames=c.ProposedStartupSeconds*60,activeFrames=c.ProposedActiveSeconds*60,recoveryFrames=c.ProposedRecoverySeconds*60,center=c.measuredContactCenter,halfSize=c.proposedHalfSize,spatialProfile=c.spatialProfile};}}
 UnityEngine.Object Owner=>action==ActionKind.ThrowAttempt?(UnityEngine.Object)moves.throwSettings:action==ActionKind.Air&&AirMove==null?Candidate:moves.PersistentOwner(Move);
 void SetProfile(TrainingMoveSpatialProfile value){if(action==ActionKind.ThrowAttempt)moves.throwSettings.spatialProfile=value;else if(action==ActionKind.Air&&AirMove==null)Candidate.spatialProfile=value;else Move.spatialProfile=value;}

 public void Reload(){if(draft!=null)DestroyImmediate(draft);draft=ScriptableObject.CreateInstance<TrainingMoveSpatialProfile>();draft.hideFlags=HideFlags.HideAndDontSave;if(Move==null)return;if(Move.spatialProfile!=null)draft.keys=Move.spatialProfile.keys.Select(x=>x.Copy()).ToArray();else{bool crouch=command==TrainingCommand.CrouchWeakKick||command==TrainingCommand.CrouchMediumKick||command==TrainingCommand.CrouchStrongKick||command==TrainingCommand.CrouchWeakPunch||command==TrainingCommand.CrouchMediumPunch||command==TrainingCommand.CrouchStrongPunch;float height=crouch?1.1f:1.55f;draft.keys=new[]{new TrainingSpatialKey{hitCenter=action==ActionKind.Air?Candidate.measuredContactCenter:Move.center,hitHalfSize=action==ActionKind.Air?Candidate.proposedHalfSize:Move.halfSize,hurt=hurtboxes.regions.Select(r=>new TrainingSpatialHurt{partId=r.stableId,center=r.shape==TrainingHurtboxShape.Box?r.center:new Vector3(0,height*.5f,0),size=r.shape==TrainingHurtboxShape.Box?r.size:new Vector3(.52f,height,.52f)}).ToArray()}};}Refresh();}
 public void Put(TrainingSpatialKey key){Undo.RecordObject(draft,"Edit spatial draft");var list=draft.keys.Where(x=>Mathf.Abs(x.frame-key.frame)>.0001f).ToList();list.Add(key);draft.keys=list.OrderBy(x=>x.frame).ToArray();Refresh();}
 public string Save(string folder="Assets/Shioka/調整Data/Fighter/Awari/Skill/Spatial"){if(!draft.Validate(out var error))return error;if(draft.keys.Any(k=>k.frame>Move.Duration*60+.001f))return "Key outside move duration";if(draft.keys.Any(k=>k.hurt.Any(h=>!hurtboxes.regions.Any(r=>r.stableId==h.partId))))return "Unknown hurt part ID";var target=Move.spatialProfile;Undo.RecordObject(Owner,"Adopt move spatial profile");if(target==null){if(!(Owner is TrainingMoveData)&&!AssetDatabase.IsValidFolder(folder))System.IO.Directory.CreateDirectory(folder);AssetDatabase.Refresh();target=ScriptableObject.CreateInstance<TrainingMoveSpatialProfile>();if(Owner is TrainingMoveData){target.name="Spatial";AssetDatabase.AddObjectToAsset(target,Owner);}else AssetDatabase.CreateAsset(target,AssetDatabase.GenerateUniqueAssetPath(folder+"/"+action+"_"+command+".asset"));Undo.RegisterCreatedObjectUndo(target,"Create move spatial profile");SetProfile(target);}Undo.RecordObject(target,"Save move spatial keys");target.keys=draft.keys.Select(x=>x.Copy()).ToArray();EditorUtility.SetDirty(target);EditorUtility.SetDirty(Owner);AssetDatabase.SaveAssetIfDirty(target);AssetDatabase.SaveAssetIfDirty(Owner);return "Saved authoritative SO; no prefab synchronization";}
 public void Refresh(){if(character==null||draft==null||Move==null)return;if(preview==null){var go=new GameObject("Authoring sprite (no combat)");go.hideFlags=HideFlags.HideAndDontSave;go.transform.SetParent(transform,false);preview=go.AddComponent<SpriteRenderer>();preview.sharedMaterial=AssetDatabase.LoadAssetAtPath<Material>("Assets/Shioka/Shared/Materials/TrialSprite.mat");if(preview.sharedMaterial==null)preview.sharedMaterial=new Material(Shader.Find("Sprites/Default"));}var key=draft.Sample(frame);if(key==null)return;float poseOffset=0;Sprite sprite=action==ActionKind.ThrowAttempt?character.provisionalPoses.Find("Throw").sprite:action==ActionKind.Air?(command==TrainingCommand.AirStrongKick?character.strongKick:character.JumpSprite):character.IdleSprite;bool active=frame>=Move.startupFrames&&frame<Move.startupFrames+Move.activeFrames;if(active){sprite=command==TrainingCommand.Light?character.weakPunch:command==TrainingCommand.Medium?character.mediumPunch:command==TrainingCommand.Heavy?character.strongPunch:sprite;string id=command==TrainingCommand.CrouchWeakPunch?"2LP":command==TrainingCommand.CrouchMediumPunch?"2MP":command==TrainingCommand.CrouchStrongPunch?"2HP":command==TrainingCommand.Slash?"5LK":command==TrainingCommand.HeavySlash?"5MK":command==TrainingCommand.StrongKick?"5HK":command==TrainingCommand.CrouchWeakKick?"2LK":command==TrainingCommand.CrouchMediumKick?"2MK":command==TrainingCommand.CrouchStrongKick||command==TrainingCommand.Sweep?"2HK":null;if(action==ActionKind.Air)id=command==TrainingCommand.Slash?"jLK":command==TrainingCommand.HeavySlash?"jMK":command==TrainingCommand.AirStrongPunch?"jHP":command==TrainingCommand.AirStrongKick||command==TrainingCommand.AirDownStrongKick?"jHK":null;if(action==ActionKind.ThrowAttempt)id="Throw";var entry=character.provisionalPoses.Find(id);if(entry!=null){sprite=entry.sprite;poseOffset=entry.offsetY;}}var sequenceSprite=Move.SequenceSpriteAt(frame);if(sequenceSprite!=null){sprite=sequenceSprite;poseOffset=0;}preview.sprite=sprite;preview.flipX=facing<0;preview.transform.localPosition=new Vector3((key.rootForward+key.visualOffset.z)*facing,key.visualOffset.y+poseOffset,0);preview.transform.localRotation=Quaternion.identity;preview.transform.localScale=Vector3.one*character.bodyCalibration.VisualScale;SceneView.RepaintAll();}
 void OnDisable(){if(preview!=null)DestroyImmediate(preview.gameObject);if(draft!=null)DestroyImmediate(draft);}
 [MenuItem("Shioka/Spatial authoring/Open editing scene")]public static void Open(){if(EditorApplication.isPlaying){Debug.LogWarning("Stop Play before spatial authoring");return;}const string path="Assets/Shioka/Development/Scenes/MoveSpatialAuthoring.unity";if(!UnityEditor.SceneManagement.EditorSceneManager.SaveCurrentModifiedScenesIfUserWantsTo())return;if(System.IO.File.Exists(path)){UnityEditor.SceneManagement.EditorSceneManager.OpenScene(path);var existing=UnityEngine.Object.FindAnyObjectByType<TrainingSpatialAuthoring>();Selection.activeGameObject=existing.gameObject;existing.Reload();SceneView.lastActiveSceneView?.LookAt(new Vector3(0,.8f,0),Quaternion.identity,2.5f);return;}var scene=UnityEditor.SceneManagement.EditorSceneManager.NewScene(UnityEditor.SceneManagement.NewSceneSetup.EmptyScene);var a=new GameObject("Move authoring - select this").AddComponent<TrainingSpatialAuthoring>();a.moves=Resources.Load<TrainingMoveSet>("TrainingMoveSet");a.hurtboxes=Resources.Load<TrainingHurtboxProfile>("TrainingHurtboxProfile");a.character=AssetDatabase.LoadAssetAtPath<TrainingApprovedCharacter>("Assets/Shioka/調整Data/Fighter/Awari/Data/AwariCharacter.asset");UnityEditor.SceneManagement.EditorSceneManager.SaveScene(scene,path);Selection.activeGameObject=a.gameObject;a.Reload();SceneView.lastActiveSceneView?.LookAt(new Vector3(0,.8f,0),Quaternion.identity,2.5f);}
}

